use serde::{Deserialize, Serialize};
use std::collections::HashMap;

impl SynTypeDiscovery { pub fn new () -> Self { Self :: default () } pub fn discover_from_syn_source (& mut self) -> anyhow :: Result < () > { let syn_paths = ["output2/wrapped-syn/src/decls/" , "submodules/syn/src/" ,] ; for base_path in & syn_paths { if let Ok (entries) = fs :: read_dir (base_path) { for entry in entries . flatten () { if entry . path () . extension () . map_or (false , | ext | ext == "rs") { if let Ok (content) = fs :: read_to_string (entry . path ()) { self . extract_types_from_code (& content) ? ; } } } } } self . discover_from_wrapped_declarations () ? ; Ok (()) } fn extract_types_from_code (& mut self , code : & str) -> anyhow :: Result < () > { if let Ok (syntax_tree) = syn :: parse_str :: < File > (code) { let mut visitor = TypeExtractorVisitor { discovery : self } ; visitor . visit_file (& syntax_tree) ; } Ok (()) } fn discover_from_wrapped_declarations (& mut self) -> anyhow :: Result < () > { let decl_invocation_path = "output2/wrapped-syn/src/decls/_decl_module_invocation.rs" ; if let Ok (content) = fs :: read_to_string (decl_invocation_path) { for line in content . lines () { if line . trim () . starts_with ("wrapped_syn_decls_") { let module_name = line . trim () . trim_end_matches (',') ; if let Some (type_name) = self . module_name_to_type (module_name) { self . discovered_types . insert (type_name . clone ()) ; self . visit_methods . insert (format ! ("visit_{}" , type_name . to_lowercase ())) ; } } } } Ok (()) } fn module_name_to_type (& self , module_name : & str) -> Option < String > { if module_name . contains ("module_not_found_") { let parts : Vec < & str > = module_name . split ("module_not_found_") . collect () ; if parts . len () == 2 { let type_part = parts [1] ; let mut chars = type_part . chars () ; if let Some (first) = chars . next () { return Some (first . to_uppercase () . collect :: < String > () + & chars . collect :: < String > ()) ; } } } else if module_name . contains ("parse") { return Some ("Parse" . to_string ()) ; } None } pub fn generate_visitor_macro (& self) -> String { let mut macro_code = String :: from ("macro_rules! impl_discovered_visitor {\n") ; macro_code . push_str ("    ($visitor_struct:ident) => {\n") ; macro_code . push_str ("        impl<'ast> Visit<'ast> for $visitor_struct {\n") ; for type_name in & self . discovered_types { let method_name = format ! ("visit_{}" , type_name . to_lowercase ()) ; macro_code . push_str (& format ! ("            fn {}(&mut self, node: &'ast syn::{}) {{\n" , method_name , type_name)) ; macro_code . push_str (& format ! ("                self.increment(\"{}\");\n" , type_name)) ; macro_code . push_str (& format ! ("                syn::visit::{}(self, node);\n" , method_name)) ; macro_code . push_str ("            }\n\n") ; } macro_code . push_str ("        }\n") ; macro_code . push_str ("    };\n") ; macro_code . push_str ("}\n") ; macro_code } pub fn generate_qa_assertions (& self) -> String { let expected_core_types = ["Item" , "Expr" , "Type" , "Pat" , "Stmt" , "File" , "Block" , "Ident"] ; let mut assertions = String :: from ("#[cfg(test)]\nmod qa_assertions {\n") ; assertions . push_str ("    use super::*;\n\n") ; assertions . push_str ("    #[test]\n") ; assertions . push_str ("    fn test_discovered_core_types() {\n") ; assertions . push_str ("        let discovery = SynTypeDiscovery::new();\n") ; for expected_type in & expected_core_types { assertions . push_str (& format ! ("        assert!(discovery.discovered_types.contains(\"{}\"), \"Missing core type: {}\");\n" , expected_type , expected_type)) ; } assertions . push_str ("    }\n\n") ; assertions . push_str ("    #[test]\n") ; assertions . push_str ("    fn test_minimum_type_coverage() {\n") ; assertions . push_str ("        let discovery = SynTypeDiscovery::new();\n") ; assertions . push_str (& format ! ("        assert!(discovery.discovered_types.len() >= {}, \"Insufficient type coverage\");\n" , expected_core_types . len ())) ; assertions . push_str ("    }\n") ; assertions . push_str ("}\n") ; assertions } pub fn report_discovery (& self) { println ! ("🔍 SYN TYPE DISCOVERY REPORT:") ; println ! ("  Discovered types: {}" , self . discovered_types . len ()) ; println ! ("  Visit methods: {}" , self . visit_methods . len ()) ; println ! ("  Enum variants: {}" , self . enum_variants . len ()) ; println ! ("\n📋 DISCOVERED TYPES:") ; let mut types : Vec < _ > = self . discovered_types . iter () . collect () ; types . sort () ; for (i , type_name) in types . iter () . enumerate () { if i % 5 == 0 { println ! () ; } print ! ("  {:15}" , type_name) ; } println ! () ; } }